tool_input.command:
gh pr view 370 --json body -q .body > /tmp/pr370_body.md
wc -l /tmp/pr370_body.md
cat -A /tmp/pr370_body.md | grep -n '\$$' | head -5
echo "---checking consecutive nonblank lines without block markers---"
awk 'BEGIN{prev=""; prevblank=1}
{
  line=$0
  isblank = (line ~ /^[[:space:]]*$/)
  if (!isblank && !prevblank) {
    # check if either prev or current line begins with block marker
    print NR": "line
  }
  prevblank = isblank
}' /tmp/pr370_body.md
